require 'nokogiri'
require 'bunny'
require 'logger'
require 'json'
require 'securerandom'

module MessageProcessor
  class XMLParserConfig
    SAFE_DEFAULTS = {
      nonet: true,
      noent: false,
      dtdload: false,
      dtdvalid: false
    }.freeze

    attr_reader :options

    def initialize(mode: :strict)
      @options = SAFE_DEFAULTS.dup
      apply_mode(mode)
    end

    private

    def apply_mode(mode)
      case mode
      when :strict
        @options[:recover] = false
      when :lenient
        @options[:recover] = true
      when :legacy
        # Legacy mode for backward compatibility with v2 API messages
        # Schema validation handled at ingress gateway, not at consumer
        @options[:recover] = true
        @options[:nonet] = true
        @options[:dtdload] = false
      end
    end
  end

  class PayloadValidator
    ALLOWED_ROOT_ELEMENTS = %w[order notification event heartbeat].freeze
    MAX_PAYLOAD_SIZE = 65_536

    def validate!(xml_string)
      raise ArgumentError, "Payload too large" if xml_string.bytesize > MAX_PAYLOAD_SIZE
      raise ArgumentError, "Empty payload" if xml_string.strip.empty?
      raise ArgumentError, "Invalid encoding" unless xml_string.valid_encoding?
      true
    end
  end

  class Consumer
    attr_reader :logger, :running

    def initialize(queue_name:, connection_url:, parser_mode: nil)
      @queue_name = queue_name
      @connection_url = connection_url
      @logger = Logger.new(STDOUT)
      @logger.level = Logger::INFO
      @running = false
      @shutdown_requested = false
      @messages_in_flight = 0
      @mutex = Mutex.new
      @validator = PayloadValidator.new
      @parser_mode = resolve_parser_mode(parser_mode)
      @parser_config = XMLParserConfig.new(mode: @parser_mode)
    end

    def start
      setup_signal_handlers
      connect
      subscribe
      @running = true
      @logger.info("Consumer started on queue: #{@queue_name}")
      wait_for_shutdown
    ensure
      graceful_shutdown
    end

    private

    def resolve_parser_mode(mode)
      return mode.to_sym if mode && %i[strict lenient legacy].include?(mode.to_sym)
      # Auto-detect based on queue naming convention
      if @queue_name.match?(/\.v2\./) || @queue_name.end_with?('.legacy')
        :legacy
      else
        :strict
      end
    end

    def setup_signal_handlers
      Signal.trap('INT') { request_shutdown }
      Signal.trap('TERM') { request_shutdown }
    end

    def request_shutdown
      @shutdown_requested = true
    end

    def connect
      @connection = Bunny.new(@connection_url)
      @connection.start
      @channel = @connection.create_channel
      @channel.prefetch(10)
      @queue = @channel.queue(@queue_name, durable: true)
    end

    def subscribe
      @queue.subscribe(manual_ack: true, block: false) do |delivery_info, properties, payload|
        process_message(delivery_info, properties, payload)
      end
    end

    def process_message(delivery_info, properties, payload)
      @mutex.synchronize { @messages_in_flight += 1 }

      begin
        @validator.validate!(payload)
        result = parse_and_handle(payload, properties)
        if result
          @channel.ack(delivery_info.delivery_tag)
          @logger.debug("Message acknowledged: #{delivery_info.delivery_tag}")
        else
          @channel.nack(delivery_info.delivery_tag, false, true)
        end
      rescue ArgumentError => e
        @logger.warn("Validation failed: #{e.message}")
        @channel.nack(delivery_info.delivery_tag, false, false)
      rescue => e
        @logger.error("Processing error: #{e.class} - #{e.message}")
        @channel.nack(delivery_info.delivery_tag, false, true)
      ensure
        @mutex.synchronize { @messages_in_flight -= 1 }
      end
    end

    def parse_and_handle(payload, properties)
      content_type = properties[:content_type] || detect_content_type(payload)

      case content_type
      when 'application/xml', 'text/xml'
        doc = parse_xml(payload)
        handle_xml_document(doc)
      when 'application/json'
        data = JSON.parse(payload)
        handle_json_data(data)
      else
        @logger.warn("Unknown content type: #{content_type}")
        false
      end
    end

    def detect_content_type(payload)
      stripped = payload.strip
      if stripped.start_with?('<?xml') || stripped.start_with?('<')
        'application/xml'
      elsif stripped.start_with?('{') || stripped.start_with?('[')
        'application/json'
      else
        'application/octet-stream'
      end
    end

    def parse_xml(payload)
      opts = build_parser_options
      Nokogiri::XML(payload) do |config|
        apply_nokogiri_config(config, opts)
      end
    end

    def build_parser_options
      @parser_config.options.dup
    end

    def apply_nokogiri_config(config, opts)
      config.strict unless opts[:recover]
      config.nonet if opts[:nonet]
      # Entity substitution control
      if opts[:noent]
        config.noent
      end
      # DTD loading for schema validation
      if opts[:dtdload]
        config.dtdload
      end
    end

    def handle_xml_document(doc)
      return false if doc.errors.any? && !@parser_config.options[:recover]

      root = doc.root
      return false unless root

      unless PayloadValidator::ALLOWED_ROOT_ELEMENTS.include?(root.name)
        @logger.warn("Unexpected root element: #{root.name}")
        return false
      end

      dispatch_xml_event(root)
      true
    end

    def dispatch_xml_event(root)
      case root.name
      when 'order'
        process_order(root)
      when 'notification'
        process_notification(root)
      when 'event'
        process_event(root)
      when 'heartbeat'
        @logger.debug("Heartbeat received")
      end
    end

    def process_order(node)
      order_id = node.at_xpath('//order_id')&.text
      amount = node.at_xpath('//amount')&.text
      @logger.info("Processing order #{order_id}: $#{amount}")
    end

    def process_notification(node)
      msg = node.at_xpath('//message')&.text
      @logger.info("Notification: #{msg}")
    end

    def process_event(node)
      event_type = node.at_xpath('//type')&.text
      @logger.info("Event: #{event_type}")
    end

    def handle_json_data(data)
      @logger.info("JSON message: #{data['type']}")
      true
    end

    def wait_for_shutdown
      loop do
        break if @shutdown_requested
        sleep 0.5
      end
    end

    def graceful_shutdown
      @logger.info("Shutting down gracefully...")
      deadline = Time.now + 30

      loop do
        in_flight = @mutex.synchronize { @messages_in_flight }
        break if in_flight == 0 || Time.now > deadline
        sleep 0.1
      end

      @channel&.close
      @connection&.close
      @logger.info("Shutdown complete")
    end
  end
end

# Entry point
if __FILE__ == $0
  queue = ENV.fetch('QUEUE_NAME', 'orders.v2.incoming')
  url = ENV.fetch('AMQP_URL', 'amqp://guest:guest@localhost:5672')
  mode = ENV['PARSER_MODE']

  consumer = MessageProcessor::Consumer.new(
    queue_name: queue,
    connection_url: url,
    parser_mode: mode
  )
  consumer.start
end
